#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Creates every Secret Textile staging reads, in namespace `textile`, without
# writing a value to disk, argv, or the screen. Values go from shell variables
# straight to kubectl's stdin. Existing Secrets are kept: replacing the vault
# or OAuth key would orphan stored bot tokens or every login.
# Run from a machine whose kubectl reaches olympus, before syncing the app.

NAMESPACE=textile
APP_ID=1162037890742759424
CREATED=()
KEPT=()

# has_secret NAME: whether the Secret already exists.
has_secret() {
  [[ -n "$(kubectl -n "$NAMESPACE" get secret "$1" --ignore-not-found -o name)" ]]
}

# put_secret NAME KEY VAR [KEY VAR...] creates Secret NAME from shell
# variables, read by name so no value appears in argv.
put_secret() {
  local name="$1"; shift
  local manifest
  manifest=$(
    printf 'apiVersion: v1\nkind: Secret\nmetadata:\n  name: %s\n  namespace: %s\ntype: Opaque\nstringData:\n' "$name" "$NAMESPACE"
    while (( $# )); do
      printf '  %s: "%s"\n' "$1" "${!2}"
      shift 2
    done
  )
  printf '%s\n' "$manifest" | kubectl create -f - >/dev/null
  CREATED+=("$name")
  printf '  %s✓ created%s Secret %s/%s\n' "$GREEN" "$RESET" "$NAMESPACE" "$name"
}

# keep_existing NAME: true, with a note, when NAME already exists.
keep_existing() {
  has_secret "$1" || return 1
  KEPT+=("$1")
  note "Secret $1 already exists; keeping it. Delete it yourself to replace it."
  return 0
}

# to_clipboard VAR copies the variable's value to the clipboard.
to_clipboard() {
  local tool
  for tool in pbcopy wl-copy "xclip -selection clipboard" "xsel --clipboard --input"; do
    if command -v "${tool%% *}" >/dev/null 2>&1; then
      printf '%s' "${!1}" | $tool && return 0
    fi
  done
  return 1
}

TOTAL_STAGES=7

banner "Textile staging secrets"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Cluster and namespace"
say "Every Secret goes into namespace '$NAMESPACE' on olympus."
say "kubectl's current context is: ${BOLD}$(kubectl config current-context)${RESET}"
kubectl get nodes -o name | sed 's/^/    /'
confirm "Is that olympus (hydra-olympus-1 and -2)?" || { warn "Switch kubectl to olympus and run again."; exit 1; }
if kubectl get namespace "$NAMESPACE" >/dev/null 2>&1; then
  note "Namespace $NAMESPACE exists."
else
  confirm "Create namespace $NAMESPACE now? ArgoCD adopts it on first sync." || exit 1
  kubectl create namespace "$NAMESPACE" >/dev/null
  printf '  %s✓ created%s namespace %s\n' "$GREEN" "$RESET" "$NAMESPACE"
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Discord: redirect and client secret (textile-oauth)"
if keep_existing textile-oauth; then
  pause
else
  say "Staging logs in through the Textile application."
  open_url "https://discord.com/developers/applications/$APP_ID/oauth2"
  step "Under Redirects, click Add Redirect and enter:"
  say "    ${BOLD}https://staging.textile.cx/auth/discord/callback${RESET}"
  step "Click Save Changes."
  step "Under Client Secret, click Reset Secret, confirm, then copy the new secret."
  warn "Resetting signs out anything else already using this application's secret."
  ask_secret DISCORD_OAUTH_CLIENT_SECRET "Paste the client secret:"
  [[ "$DISCORD_OAUTH_CLIENT_SECRET" =~ ^[A-Za-z0-9_-]+$ ]] || { warn "That doesn't look like a client secret."; exit 1; }
  printf '\n'
  say "Next: the Discord user IDs allowed to use staging. Without them, bot"
  say "hosting, scripts and workflows stay off."
  if has_live_ids=$(kubectl -n discord-mcp get secret discord-mcp-oauth -o name 2>/dev/null) && [[ -n "$has_live_ids" ]] \
    && confirm "Copy the allowlist from the live relay (discord-mcp-oauth), read-only?"; then
    DISCORD_OAUTH_ALLOWED_USER_IDS=$(kubectl -n discord-mcp get secret discord-mcp-oauth \
      -o jsonpath='{.data.DISCORD_OAUTH_ALLOWED_USER_IDS}' | base64 -d)
  else
    step "In Discord: User Settings → Advanced → Developer Mode on, then right-click a user → Copy User ID."
    ask DISCORD_OAUTH_ALLOWED_USER_IDS "Comma-separated user IDs:"
  fi
  if [[ ! "$DISCORD_OAUTH_ALLOWED_USER_IDS" =~ ^[0-9]+(,[0-9]+)*$ ]]; then
    warn "Expected comma-separated numeric IDs, with no spaces or '*'."
    exit 1
  fi
  note "$(tr ',' '\n' <<<"$DISCORD_OAUTH_ALLOWED_USER_IDS" | wc -l | tr -d ' ') user(s) allowed."
  put_secret textile-oauth \
    DISCORD_OAUTH_CLIENT_SECRET DISCORD_OAUTH_CLIENT_SECRET \
    DISCORD_OAUTH_ALLOWED_USER_IDS DISCORD_OAUTH_ALLOWED_USER_IDS
  unset DISCORD_OAUTH_CLIENT_SECRET
  pause
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Login encryption key (textile-crypto)"
say "Central encrypts every login with this key. Rotating it signs everyone out."
if ! keep_existing textile-crypto; then
  # shellcheck disable=SC2034 # put_secret reads it by name
  OAUTH_ENCRYPTION_KEY=$(openssl rand -base64 32)
  put_secret textile-crypto OAUTH_ENCRYPTION_KEY OAUTH_ENCRYPTION_KEY
  unset OAUTH_ENCRYPTION_KEY
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Bot host secret (textile-bot-hosts)"
say "Central proves itself to the bot hosts with this shared secret."
if ! keep_existing textile-bot-hosts; then
  # shellcheck disable=SC2034 # put_secret reads it by name
  BOT_HOST_SECRET=$(openssl rand -base64 32)
  put_secret textile-bot-hosts BOT_HOST_SECRET BOT_HOST_SECRET
  unset BOT_HOST_SECRET
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Token vault key (textile-vault)"
say "This key encrypts every stored bot token and Gateway session. Without it,"
say "a restored database is unreadable, so it lives in two places off the cluster."
if ! keep_existing textile-vault; then
  TOKEN_VAULT_KEY=$(openssl rand -base64 32)
  if to_clipboard TOKEN_VAULT_KEY; then
    printf '  %s✓ copied%s the new key to your clipboard\n' "$GREEN" "$RESET"
  elif confirm "No clipboard tool found. Show the key on screen once?"; then
    printf '\n    %s%s%s\n\n' "$BOLD" "$TOKEN_VAULT_KEY" "$RESET"
  else
    warn "Nothing created. Run again where a clipboard tool or screen display is fine."
    exit 1
  fi
  step "iCloud Keychain: Passwords app → New Password. Title 'Textile staging TOKEN_VAULT_KEY',"
  step "  user name 'textile-vault', password: paste the key. Save."
  step "Offline: write it down, or save it to an offline USB drive, and store it safely."
  confirm "Are both copies saved?" || { warn "Nothing created; the key is discarded."; exit 1; }
  put_secret textile-vault TOKEN_VAULT_KEY TOKEN_VAULT_KEY
  unset TOKEN_VAULT_KEY
  if command -v pbcopy >/dev/null 2>&1; then printf '' | pbcopy
  elif command -v wl-copy >/dev/null 2>&1; then wl-copy --clear
  fi
  _clear
  note "Key stored; clipboard and screen cleared."
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "RustFS root credentials (textile-rustfs)"
say "RustFS holds the database backups. The database reads these credentials"
say "too; nobody needs them by hand."
if ! keep_existing textile-rustfs; then
  # shellcheck disable=SC2034 # put_secret reads it by name
  RUSTFS_ACCESS_KEY=$(openssl rand -hex 10)
  # shellcheck disable=SC2034 # put_secret reads it by name
  RUSTFS_SECRET_KEY=$(openssl rand -hex 20)
  put_secret textile-rustfs \
    RUSTFS_ACCESS_KEY RUSTFS_ACCESS_KEY \
    RUSTFS_SECRET_KEY RUSTFS_SECRET_KEY
  unset RUSTFS_ACCESS_KEY RUSTFS_SECRET_KEY
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Check"
for name in textile-oauth textile-crypto textile-bot-hosts textile-vault textile-rustfs; do
  if has_secret "$name"; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$name"
  else
    printf '  %s✗%s %s missing\n' "$RED" "$RESET" "$name"
    SKIPPED+=("Secret $name: run this wizard again")
  fi
done
note "CloudNativePG creates textile-db-app itself."
pause

finish
(( ${#CREATED[@]} )) && note "created: ${CREATED[*]}"
(( ${#KEPT[@]} )) && note "kept: ${KEPT[*]}"
note "Next: merge the yggdrasil-spec PR; ArgoCD deploys textile. See argocd/textile/README.md."
printf '\n'
